import{z as n,x as A,o as t,c as B,q as E,j as o,D as e,d as i,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"调制与符号率","description":"","frontmatter":{"title":"调制与符号率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/modulation-symbol-rate.md","filePath":"cs/modulation-symbol-rate.md","lastUpdated":1791063341000}'),d={name:"cs/modulation-symbol-rate.md"};function p(_,a,m,c,h,P){const s=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="调制与符号率" tabindex="-1">调制与符号率 <a class="header-anchor" href="#调制与符号率" aria-label="Permalink to &quot;调制与符号率&quot;">​</a></h1><div class="epigraph"><p>波特是符号率，不是比特率；每符号 $\\log_2 M$ 比特叠在同一带宽上，噪声一升就必须降阶。</p><footer>—— 据 Proakis, Digital Communications；IEEE 802.3 各代 PAM / QAM 条款整理</footer></div><p><a href="/cs/shannon-capacity-link">上一课</a>把一跳钉在 \\(C=B\\log_2(1+\\mathrm{SNR})\\)，还没有说波形怎么占 \\(B\\)。缺口是<strong>调制</strong>：基带 PAM、带通 QAM/PSK 把离散符号映到脉冲或载波；符号率 \\(R_s\\) 与每符号比特共同决定毛比特率。本课不把 8B/10B 的游程写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>容量给上界，网卡发出的是连续时间波形。符号间隔 \\(T=1/R_s\\)，占用大约 \\(B\\sim R_s/2\\)（升余弦等成形再加滚降）。同一 \\(R_s\\) 上，\\(M\\)-PAM 每符号 \\(\\log_2 M\\) 比特，SNR 不够则星座点重叠。千兆铜缆用 PAM-5，更快的以太网用 PAM-4：每符号比特加倍，对噪声更苛刻——这是在 \\(C\\) 下面移动工作点，不是改写香农公式。</p><p>比特率 \\(=R_s\\cdot\\log_2 M\\cdot\\) 码率。营销「10G」混着线路码开销，后课再拆。</p><p><span class="marginnote">数字实例：千兆铜缆符号率约 125 MBd。用 PAM-2（每符号 1 比特）毛速率是 125 Mb/s；换成 PAM-4（每符号 2 比特），同样的波特率就翻到 250 Mb/s——「不改电缆、只改星座」就能提速。</span></p><p><span class="marginnote">Nyquist 脉冲保证无 ISI 的符号率上限。实际电缆有频率选择性，后课均衡与 FEC 补。本课只钉符号 vs 比特。</span></p><h3 id="波特不是比特率" tabindex="-1">波特不是比特率 <a class="header-anchor" href="#波特不是比特率" aria-label="Permalink to &quot;波特不是比特率&quot;">​</a></h3><p>口头把 baud 说成 bit/s 会把 PAM-4 的每符号两比特算丢。本课之后「链路速率」默认指毛比特率，开销另扣。自适应降阶是改 \\(M\\)，不是改电缆。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：NRZ（\\(M=2\\)）最省眼图，频谱宽；高阶 PAM/QAM 省带宽、要 SNR。画发送：比特 → 分组为符号 → 脉冲成形 → 介质。接收：匹配滤波、抽样、判决。不要把「波特率」口头说成比特率。</p>',12)),(t(),o(r,null,{default:e(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BITS%5B%22%E6%AF%94%E7%89%B9%22%5D%20--%3E%20SYM%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%20M%20%E5%85%83%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20SYM%20--%3E%20PULSE%5B%22%E6%88%90%E5%BD%A2%2C%20%E7%AC%A6%E5%8F%B7%E7%8E%87%20Rs%22%5D%0A%20%20PULSE%20--%3E%20WIRE%5B%22%E5%8D%A0%E5%B8%A6%E5%AE%BD%20B%22%5D%0A%20%20WIRE%20--%3E%20DEC%5B%22%E6%8A%BD%E6%A0%B7%E5%88%A4%E5%86%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主干<a href="/cs/csma-switch">CSMA 与交换</a>假定全双工链路上已有双向比特。那些比特来自本课的符号流。交换机背板后课再谈；这里只承认：端口「速率」是调制与码共同产物。无线后课的 OFDM 把同一思想搬到多载波，不在本课展开。</p><p>眼图闭合 = ISI 或噪声吃掉星座间距。降阶（从 PAM-4 回到 PAM-2）是自适应，不是协议错误。</p><p><span class="marginnote">直觉类比：把星座点间距想成楼梯台阶的高度。PAM-2 是两级宽台阶，落脚偏一点仍在本级；PAM-4 是四级窄台阶，噪声像地面震动——台阶越密越容易踩进相邻级，这就是「高阶对 SNR 更苛刻」的直观含义。</span></p><p><span class="marginnote">常见误区：初学者容易以为「10G 网卡」每秒真能交付 10 Gbit 有效数据。实际那是毛比特率：还要扣掉线路码开销、前导码与 FEC 冗余，应用层看到的吞吐会明显打折。</span></p><p>降阶的自适应回路长这样：</p>',6)),(t(),o(r,null,{default:e(()=>[l(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20TX%5B%22%E5%8F%91%E9%80%81%E7%AB%AF%E7%94%A8%20PAM-4%22%5D%20--%3E%20CHAN%5B%22%E4%BF%A1%E9%81%93%3A%20%E5%99%AA%E5%A3%B0%E4%B8%8E%20ISI%22%5D%0A%20%20CHAN%20--%3E%20EYE%7B%22%E6%8E%A5%E6%94%B6%E7%AB%AF%E7%9C%BC%E5%9B%BE%E5%BC%A0%E5%BC%80%3F%22%7D%0A%20%20EYE%20--%20%22%E5%BC%A0%E5%BC%80%22%20--%3E%20KEEP%5B%22%E7%BB%B4%E6%8C%81%204%20%E9%98%B6%2C%20%E6%AF%8F%E7%AC%A6%E5%8F%B7%202%20%E6%AF%94%E7%89%B9%22%5D%0A%20%20EYE%20--%20%22%E9%97%AD%E5%90%88%22%20--%3E%20DROP%5B%22%E9%99%8D%E9%98%B6%E5%9B%9E%20PAM-2%22%5D%0A%20%20DROP%20--%3E%20RELI%5B%22%E7%89%BA%E7%89%B2%E9%80%9F%E7%8E%87%E6%8D%A2%E5%8F%96%E5%8F%AF%E9%9D%A0%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导匹配滤波器的充分统计量全文，不引入 Coset 编码。线路码的直流平衡与时钟含量是下一课。后课默认：毛比特率 = 符号率 × 每符号比特 × 码率。</p><p>调制不提供端到端可靠：判决错误交给 FEC 或上层重传。<a href="/cs/layering-e2e">端到端</a> 仍在两端收口。</p><p>下一课<a href="/cs/line-coding">线路编码 4B/5B、8B/10B</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>符号率（波特）占带宽；每符号比特由星座阶数决定。</li><li>高阶调制贴近 \\(C\\)，对 SNR 敏感。</li><li>「链路速率」已含这一层选择，尚未含 4B/5B 开销。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Proakis；IEEE 802.3；Nyquist 成形。</li></ul>',6))])}const C=n(d,[["render",p]]);export{M as __pageData,C as default};
